package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
/** Explicit local notes and continuation cards. No automatic recording or sending. */
final class PersonalNotes {
 static synchronized JSONArray all(Context c)throws Exception {try{JSONArray rows=ConversationWorkspace.read(c,"personal-notes").getJSONArray("items");if(rows.length()>200)throw new IOException("メモ件数が不正です。元データは保持しています");return rows;}catch(FileNotFoundException absent){return new JSONArray();}}
 static synchronized JSONArray list(Context c)throws Exception{JSONArray rows=all(c),out=new JSONArray();for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optLong("deletedAt")==0)out.put(rows.get(i));return out;}
 static synchronized JSONArray trash(Context c)throws Exception{JSONArray rows=all(c),out=new JSONArray();for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optLong("deletedAt")>0)out.put(rows.get(i));return out;}
 static synchronized JSONObject detail(Context c,String id)throws Exception{JSONArray rows=all(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id")))return row;}throw new IOException("メモがありません");}

 static synchronized JSONObject save(Context c,JSONObject v)throws Exception {
  String id=v.getString("id"),kind=v.getString("kind"),text=v.getString("text").trim();
  if(!id.matches("[a-f0-9-]{36}")||!kind.matches("memo|continuation")||text.isEmpty()||text.length()>2400)throw new IOException("メモの内容・種類を確認してください");
  JSONArray rows=all(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))){if(row.optLong("deletedAt")>0)throw new IOException("削除済みです。ごみ箱から明示的に復元してください");if(!text.equals(row.getString("text"))||!kind.equals(row.getString("kind")))throw new IOException("同じ保存IDの内容が異なります");return row;}}
  if(list(c).length()>=100||rows.length()>=200)throw new IOException("メモは100件までです。不要な記録を整理してください");
  JSONObject row=new JSONObject().put("id",id).put("kind",kind).put("text",text).put("revision",1).put("at",System.currentTimeMillis());rows.put(row);ConversationWorkspace.write(c,"personal-notes",new JSONObject().put("items",rows));return row;
 }
 static synchronized JSONObject defer(Context c,String id)throws Exception{JSONArray rows=list(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id")))return SecretaryInbox.save(c,row.getString("text"),"利用者がメモから保存",id);}throw new IOException("メモが削除されています。開き直してください");}
 static synchronized void delete(Context c,String id)throws Exception{JSONArray rows=all(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))&&row.optLong("deletedAt")==0){ReviewStore.history(row);row.put("deletedAt",System.currentTimeMillis()).put("revision",row.optInt("revision",1)+1);ConversationWorkspace.write(c,"personal-notes",new JSONObject().put("items",rows));return;}}throw new IOException("メモが削除・更新されています");}
 static synchronized JSONObject change(Context c,JSONObject input)throws Exception{JSONArray rows=all(c);String id=input.getString("id"),action=input.getString("action"),change=input.getString("changeId");ReviewStore.validId(change);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!id.equals(row.getString("id")))continue;String fingerprint=ReviewStore.hash(input);if(change.equals(row.optString("changeId"))){if(!fingerprint.equals(row.optString("changeHash")))throw new IOException("同じ操作IDの内容が異なります");return row;}if(input.getInt("revision")!=row.optInt("revision",1))throw new IOException("メモが更新されています。開き直してください");if(action.equals("purge")){if(row.optLong("deletedAt")==0)throw new IOException("ごみ箱の記録だけ完全削除できます");JSONArray next=new JSONArray();for(int j=0;j<rows.length();j++)if(j!=i)next.put(rows.get(j));ConversationWorkspace.write(c,"personal-notes",new JSONObject().put("items",next));return new JSONObject().put("purged",true);}if(action.equals("restore")){if(row.optLong("deletedAt")==0)throw new IOException("削除済みではありません");if(list(c).length()>=100)throw new IOException("復元先のメモが100件です");ReviewStore.history(row);row.remove("deletedAt");}else{if(row.optLong("deletedAt")>0)throw new IOException("先にごみ箱から復元してください");String text;if(action.equals("edit"))text=input.getString("text").trim();else if(action.equals("undo")){JSONArray history=row.optJSONArray("history");int index=input.getInt("index");if(history==null||index<0||index>=history.length())throw new IOException("履歴がありません");text=history.getJSONObject(index).optString("text");}else throw new IOException("操作が不正です");if(text.isEmpty()||text.length()>2400)throw new IOException("メモは1〜2400文字です");ReviewStore.history(row);row.put("text",text);}row.put("revision",row.optInt("revision",1)+1).put("updatedAt",System.currentTimeMillis()).put("changeId",change).put("changeHash",fingerprint);ConversationWorkspace.write(c,"personal-notes",new JSONObject().put("items",rows));return row;}throw new IOException("メモがありません");}
 private PersonalNotes(){}
}
